#!/bin/sh
# Generated by FWShift: IP groups, network services and Cloud Firewall filtering rules for Zscaler Internet
# Access, created through the ZIA API. Read the report first: what is disabled or left out is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                                                   prints the calls, makes none
#   ZIA_BASE=https://api.zsapi.net/zia/api/v1 ZIA_TOKEN=... sh THIS_FILE      OneAPI (ZIdentity) token
#   ZIA_BASE=https://zsapi.<cloud>.net/api/v1 ZIA_SESSION=... sh THIS_FILE     JSESSIONID of a legacy session
#
# Nothing is activated: POST /status/activate is left to you. A legacy session that ends (logout, or its
# timeout) activates what was changed in it. The script stops at the first call that is refused, and at a name
# that is taken; what it created is in $JOURNAL (path, id, name), to delete again if need be.
set -eu
DRY_RUN="${DRY_RUN:-}"
JOURNAL="${JOURNAL:-zia-fwshift-created.txt}"
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT
if [ -z "$DRY_RUN" ]; then
  : "${ZIA_BASE:?set ZIA_BASE to the base URL of the ZIA API}"
  command -v jq >/dev/null || { echo "jq is needed" >&2; exit 1; }
  if [ -n "${ZIA_TOKEN:-}" ]; then AUTH="Authorization: Bearer $ZIA_TOKEN"
  elif [ -n "${ZIA_SESSION:-}" ]; then AUTH="Cookie: JSESSIONID=$ZIA_SESSION"
  else echo "set ZIA_TOKEN (OneAPI) or ZIA_SESSION (legacy API session)" >&2; exit 1; fi
fi
call() {  # call METHOD PATH [BODY-FILE]: the answer on stdout
  tries=0
  while :; do
    if [ -n "${3:-}" ]; then
      code=$(curl -sS -o "$OUT/answer" -D "$OUT/headers" -w '%{http_code}' -X "$1" -H "$AUTH" -H 'Content-Type: application/json' \
             --data-binary @"$3" "$ZIA_BASE$2")
    else
      code=$(curl -sS -o "$OUT/answer" -D "$OUT/headers" -w '%{http_code}' -X "$1" -H "$AUTH" "$ZIA_BASE$2")
    fi
    case "$code" in
      2??) cat "$OUT/answer"; sleep 1; return 0 ;;
      429) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "rate limited: $1 $2" >&2; return 1; }
           wait=$(sed -n 's/^[Rr]etry-[Aa]fter: *\([0-9]*\).*/\1/p' "$OUT/headers"); sleep "${wait:-2}" ;;
      *) echo "HTTP $code on $1 $2:" >&2; cat "$OUT/answer" >&2; return 1 ;;
    esac
  done
}
lookup() {  # lookup PATH NAME: the id of the entry of exactly that name, or nothing (the name is compared here)
  case "$1" in /firewallFilteringRules) query="" ;; *) query="?search=$(jq -rn --arg v "$2" '$v|@uri')&pageSize=1000" ;; esac
  answer=$(call GET "$1$query")
  printf '%s' "$answer" | jq -r --arg n "$2" '[.[] | select(.name == $n) | .id][0] // empty'
}
need() {  # need PATH NAME DRY-ID: the id of an entry the tenant must have
  if [ -n "$DRY_RUN" ]; then printf 'GET %s (name %s)\n' "$1" "$2" >&2; echo "$3"; return 0; fi
  id=$(lookup "$1" "$2")
  [ -n "$id" ] || { echo "not on the tenant: $2 ($1)" >&2; return 1; }
  echo "$id"
}
create() {  # create PATH NAME BODY-FILE DRY-ID: the id of the new entry; refuses a name that is taken
  if [ -n "$DRY_RUN" ]; then printf 'POST %s\n' "$1" >&2; cat "$3" >&2; printf '\n' >&2; echo "$4"; return 0; fi
  taken=$(lookup "$1" "$2")
  [ -z "$taken" ] || { echo "the name is taken: $2 ($1); nothing of it is changed" >&2; return 1; }
  answer=$(call POST "$1" "$3")
  id=$(printf '%s' "$answer" | jq -r '.id // empty')
  [ -n "$id" ] || { echo "no id in the answer to POST $1" >&2; return 1; }
  printf '%s %s %s\n' "$1" "$id" "$2" >> "$JOURNAL"
  echo "$id"
}

ID_1=$(need /locations 'inside_zone' 1)
cat > "$OUT/2.json" <<FWSHIFT_JSON
{"name": "fws-iot-net", "ipAddresses": ["10.41.0.0/24"], "description": "FWShift"}
FWSHIFT_JSON
ID_2=$(create /ipSourceGroups 'fws-iot-net' "$OUT/2.json" 2)
cat > "$OUT/3.json" <<FWSHIFT_JSON
{"name": "fws-office-lan", "ipAddresses": ["10.40.0.0/24"], "description": "FWShift"}
FWSHIFT_JSON
ID_3=$(create /ipSourceGroups 'fws-office-lan' "$OUT/3.json" 3)
cat > "$OUT/4.json" <<FWSHIFT_JSON
{"name": "fws-web", "destTcpPorts": [{"start": 80}, {"start": 443}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_4=$(create /networkServices 'fws-web' "$OUT/4.json" 4)
cat > "$OUT/5.json" <<FWSHIFT_JSON
{"name": "fws-DNS_over_UDP", "destUdpPorts": [{"start": 53}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_5=$(create /networkServices 'fws-DNS_over_UDP' "$OUT/5.json" 5)
cat > "$OUT/6.json" <<FWSHIFT_JSON
{"name": "fws-vendor-cloud", "type": "DSTN_FQDN", "addresses": ["telemetry.example.net"], "description": "FWShift"}
FWSHIFT_JSON
ID_6=$(create /ipDestinationGroups 'fws-vendor-cloud' "$OUT/6.json" 6)
cat > "$OUT/7.json" <<FWSHIFT_JSON
{"name": "fws-HTTPS", "destTcpPorts": [{"start": 443}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_7=$(create /networkServices 'fws-HTTPS' "$OUT/7.json" 7)
ID_8=$(need /locations 'outside_zone' 8)
cat > "$OUT/9.json" <<FWSHIFT_JSON
{"name": "fws-nas-web", "destTcpPorts": [{"start": 5001}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_9=$(create /networkServices 'fws-nas-web' "$OUT/9.json" 9)
cat > "$OUT/10.json" <<FWSHIFT_JSON
{"name": "fws-udp-src-53-dst-1024-65535", "destUdpPorts": [{"start": 1024, "end": 65535}], "srcUdpPorts": [{"start": 53}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_10=$(create /networkServices 'fws-udp-src-53-dst-1024-65535' "$OUT/10.json" 10)
cat > "$OUT/11.json" <<FWSHIFT_JSON
{"name": "fws-printers", "ipAddresses": ["10.40.0.200-10.40.0.220"], "description": "FWShift"}
FWSHIFT_JSON
ID_11=$(create /ipSourceGroups 'fws-printers' "$OUT/11.json" 11)

# Firewall filtering rules, from order 1 on, in the order of the converted policy.
cat > "$OUT/12.json" <<FWSHIFT_JSON
{"name": "fws-Block_IoT_to_office", "order": 1, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_2}}], "destAddresses": ["10.40.0.0/24", "192.0.2.10"]}
FWSHIFT_JSON
ID_12=$(create /firewallFilteringRules 'fws-Block_IoT_to_office' "$OUT/12.json" 12)
cat > "$OUT/13.json" <<FWSHIFT_JSON
{"name": "fws-Inside_Outside_web", "order": 2, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_3}}], "nwServices": [{"id": ${ID_4}}, {"id": ${ID_5}}]}
FWSHIFT_JSON
ID_13=$(create /firewallFilteringRules 'fws-Inside_Outside_web' "$OUT/13.json" 13)
cat > "$OUT/14.json" <<FWSHIFT_JSON
{"name": "fws-IoT_telemetry", "order": 3, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_2}}], "destIpGroups": [{"id": ${ID_6}}], "nwServices": [{"id": ${ID_7}}]}
FWSHIFT_JSON
ID_14=$(create /firewallFilteringRules 'fws-IoT_telemetry' "$OUT/14.json" 14)
cat > "$OUT/15.json" <<FWSHIFT_JSON
{"name": "fws-NAS_from_Internet", "order": 4, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_8}}], "destAddresses": ["10.40.0.10", "192.0.2.2", "192.0.2.10"], "nwServices": [{"id": ${ID_9}}]}
FWSHIFT_JSON
ID_15=$(create /firewallFilteringRules 'fws-NAS_from_Internet' "$OUT/15.json" 15)
cat > "$OUT/16.json" <<FWSHIFT_JSON
{"name": "fws-DNS_answers", "order": 5, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_8}}], "nwServices": [{"id": ${ID_10}}]}
FWSHIFT_JSON
ID_16=$(create /firewallFilteringRules 'fws-DNS_answers' "$OUT/16.json" 16)
cat > "$OUT/17.json" <<FWSHIFT_JSON
{"name": "fws-Staff_streaming", "order": 6, "rank": 7, "action": "BLOCK_DROP", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_1}}]}
FWSHIFT_JSON
ID_17=$(create /firewallFilteringRules 'fws-Staff_streaming' "$OUT/17.json" 17)
cat > "$OUT/18.json" <<FWSHIFT_JSON
{"name": "fws-Guests_by_time", "order": 7, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_11}}]}
FWSHIFT_JSON
ID_18=$(create /firewallFilteringRules 'fws-Guests_by_time' "$OUT/18.json" 18)
cat > "$OUT/19.json" <<FWSHIFT_JSON
{"name": "fws-block the rest", "order": 8, "rank": 7, "action": "BLOCK_DROP", "state": "DISABLED", "description": "FWSHIFT: what the converted policy does not allow. Enable after looking at the rules below"}
FWSHIFT_JSON
ID_19=$(create /firewallFilteringRules 'fws-block the rest' "$OUT/19.json" 19)
echo "done: nothing is active until the changes are activated (POST /status/activate)" >&2
